 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each 2x2 object is surrounded by four corner markers. Rotate the
    # marker colors clockwise to the four outward diagonal rays.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                blocks.append((r, c))
    for r, c in blocks:
        corners = [(r-1, c-1), (r-1, c+2), (r+2, c-1), (r+2, c+2)]
        if not all(0 <= rr < h and 0 <= cc < w for rr, cc in corners):
            continue
        tl, tr, bl, br = (grid[rr][cc] for rr, cc in corners)
        starts = [
            (r-1, c-1, bl, -1, -1),
            (r-1, c+2, tl, -1, 1),
            (r+2, c-1, br, 1, -1),
            (r+2, c+2, tr, 1, 1),
        ]
        for sr, sc, color, dr, dc in starts:
            rr, cc = sr, sc
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out
